function normalize_date_value(?string $v):?string{if($v===null||trim($v)===''||str_starts_with(trim($v),'0000-00-00'))return null;$v=trim($v);foreach(['Y-m-d H:i:s','Y-m-d','m/d/Y H:i:s','m/d/Y','n/j/Y'] as $fmt){$d=DateTime::createFromFormat($fmt,$v);if($d!==false)return $d->format(str_contains($fmt,'H:')?'Y-m-d H:i:s':'Y-m-d');}return null;}
function normalize_value(string $table,string $column,mixed $v):mixed{if($v==='')return null;if(in_array($column,['invoice_date','comment_time','created_at','updated_at','date_added','date_updated','edit_date','initiated_at','collection_at','collected_at','paid_date'],true))return normalize_date_value((string)$v);if(in_array($column,['due_date','adjustment_date','received_date','statement_month'],true)&&$column!=='statement_month')return normalize_date_value((string)$v);if(in_array($column,['total_amount','paid_amount','balance','unit_price','quantity','total_price','discount','total_payment','outstanding_balance','total_billed','amount_paid'],true)){return is_numeric(str_replace(',','',(string)$v)?str_replace(',','',(string)$v):$v)?(float)str_replace(',','',(string)$v):null;}return $v;}
foreach($map as $file=>$table){$path=$dir.'/'.$file;if(!is_file($path)){echo "Missing $file\n";continue;}$hash=hash_file('sha256',$path);$check=$pdo->prepare('SELECT id FROM import_runs WHERE source_name=? AND source_hash=?');$check->execute([$file,$hash]);if($check->fetch()){echo "Already imported: $file\n";continue;}$fh=fopen($path,'r');$headers=fgetcsv($fh);if(!$headers){fclose($fh);continue;}$names=array_map(fn($h)=>preg_replace('/[^a-z0-9_]/i','_',strtolower(trim($h))),$headers);$rows=$imported=$skipped=0;$insertCache=[];while(($row=fgetcsv($fh))!==false){$rows++;$row=array_pad($row,count($names),null);$vals=[];foreach($names as $i=>$n){$vals[$n]=normalize_value($table,$n,$row[$i]??null);}
 if($table==='legacy_member_accounts'){$vals['primary_email']=$vals['prm_email']??null;$vals['phone']=$vals['phone']??null;$vals['cell_phone']=$vals['cell_ph']??null;$vals['invoice_service_log']=$vals['invoice_ids']??null;$vals['total_billed']=$vals['balance']??null;$vals['amount_paid']=0;$vals['outstanding_balance']=$vals['balance']??null;unset($vals['prm_email'],$vals['cell_ph'],$vals['invoice_ids'],$vals['bus_name']);}
 $allowed=[];$cols=$pdo->query('DESCRIBE '.$table)->fetchAll();$allowed=array_column($cols,'Field');$vals=array_intersect_key($vals,array_flip($allowed));if(!$vals){$skipped++;continue;}
 $dbcols=array_keys($vals);$key=$table.implode('|',array_keys($vals));if(!isset($insertCache[$key])){$insertCache[$key]=$pdo->prepare('INSERT INTO '.$table.'('.implode(',',$dbcols).') VALUES('.implode(',',array_fill(0,count($dbcols),'?')).')');}
 try{$insertCache[$key]->execute(array_values($vals));$imported++;}catch(Throwable $e){$skipped++;}}
fclose($fh);$pdo->prepare('INSERT INTO import_runs(source_name,source_hash,rows_seen,rows_imported,rows_skipped,notes) VALUES(?,?,?,?,?,?)')->execute([$file,$hash,$rows,$imported,$skipped,'Raw legacy copy; duplicate exports skipped; malformed dates normalized to NULL; sensitive raw credentials/card data remain in staging only and must not be used by live workflows.']);echo "$file: $imported imported, $skipped skipped of $rows\n";}
foreach($dup as $file)echo "Duplicate source intentionally ignored: $file\n";
